      "summary": "这组照片记录了中国考古报告集《城子崖》及相关北平研究院工作报告的展品。展签文字可辨《城子崖》为民国二十三年（1934年）国立中央研究院历史语言研究所出版，另有1935、1936年的工作报告。",
      "description": "展签与书影可辨《城子崖》为中国考古报告集之一，全称涉及“山东历城县龙山镇之黑陶文化遗址”，著者包括傅斯年、李济、董作宾、梁思永、吴金鼎、郭宝钧、刘峙霞等人，由国立中央研究院历史语言研究所于南京出版，中华民国二十三年（1934年）。另一展签涉及《国立北平研究院第六年工作报告》与《第七年工作报告》，分别于1935年与1936年9月9日印制。照片可见为图书及报告展品。",
      "significance": "《城子崖》作为中国考古学早期重要报告集，对龙山文化黑陶遗址的公布与考古学方法的确立具有标志性意义。北平研究院工作报告则反映同期学术机构的田野工作记录。此组展品可用于展示中国考古学早期报告出版与学科建设历程。",
      "viewing_notes": "先辨认《城子崖》书影中的书名、著者与出版信息，再分别查看两册工作报告的标题与印制日期。可对比各书版式与出版机构信息。",
