      "description": "展签可辨《考古图》为（北宋）吕大临撰，亦政堂藏板，清乾隆十七年（1752）重刻本，英文标注为Lu Dalin, Kaogutu (Illustrated Antiques Atlas), Yizhengtang version, reprinted in 1752。书页展签文字可见“京兆吕氏”“高四寸四分深三寸”“铭三字”“虢叔作”“方彝”“周敦”等著录文字，并有“天都黄晓峰定”“壬申秋月”等版刻信息。照片可见为古籍书页及展签。",
