      "description": "展签可辨器物名称为彩陶瓮（Painted pottery urn），年代为仰韶时期（距今6800-4800年），出土地点为1997年华县泉护村遗址H1073a。照片中可见彩陶瓮为大型容器，器形为敛口鼓腹或直口深腹形态，器表施有彩绘纹饰。纹饰的具体母题与构图在照片中可部分辨认，但展签未提供纹饰描述。器物高度、口径等尺寸信息未标注，保存状况可从照片观察。",
      "significance": "彩陶瓮属于仰韶时期大型彩陶容器，泉护村遗址是关中地区仰韶文化的重要遗址，该标本可用于讨论仰韶时期大型容器的制作技术、彩陶装饰风格及其与遗址堆积单位的关系。展签仅提供发现单位编号，未说明其用途（贮藏或葬具），故功能判断不能展开。",
      "viewing_notes": "先看展签确认名称与出土信息，再看器物照片观察整体轮廓。注意瓮的口沿形态、肩腹交接和底部结构，彩绘部分需重点观察纹饰的分布带与图案单元。若有局部照片，比较纹饰在不同器面的连续关系。",
      "evidence_note": "展签/展签文字直接支持：名称（彩陶瓮）、年代（仰韶时期距今6800-4800年）、发现地点（1997年华县泉护村遗址H1073a）、材质（陶）。未确认而留空：尺寸、纹饰具体描述、完整度、用途。",
