      "summary": "这组照片记录了龙山时期出土的石臼、玉器、骨器与陶制工具，涉及佳县石摞摞山石城与府谷寨山遗址等多个地点。照片含展签与器物多角度视图，可观察不同材质的器类及其保存状态。",
      "description": "展签可辨器物包括石臼、穿孔石刀、陶拍、骨匕、骨针、骨簪（残）以及多种玉器：玉柄形器（含残件）、穿孔坠饰、玉饰（残）、玉环（残）、玉刀、玉锥形器。另有展签文字可辨“玉镇”但字迹不清。年代均为龙山时期（距今4800-4000年），出土地点涉及2003年佳县石摞摞山石城H3、2019年府谷寨山遗址M2、M4及1999年神木新华遗址M27。各器物可见基本器形，但尺寸、具体残损程度与加工痕迹需实物照片确认。",
      "significance": "这批组合涵盖龙山时期不同遗址出土的石质工具、玉器与骨角器，可用于讨论当时生产工具的种类构成、玉器器类及区域间玉器风格的比较。因展签未提供完整出土背景说明，其价值主要在于作为多遗址材料的组合记录，为龙山时期物质文化比较研究提供基础标本。",
      "viewing_notes": "先按展签照片顺序逐件确认名称与出土地点，再分别观察石臼的臼窝形态、玉刀的刃部与穿孔坠饰的钻孔方式、骨针的细长形态。注意区分不同遗址出土的器物，对照展签中模糊的“府谷寨山”与“石摞摞山”等文字。",
