      "title": "李家铸铜作坊与周原铸铜遗存",
      "category": "遗址与铸铜遗物",
      "period": "西周（公元前1046-前771年）",
      "dimensions": "",
      "findspot": "周原遗址；2002年扶风齐家墓地M4",
      "material": "铜、陶（范）、骨",
      "theme": "西周铸铜手工业",
      "summary": "这组照片记录周原李家铸铜作坊的说明展板及2002年扶风齐家墓地M4出土的青铜容器。展板介绍铸铜原料、陶范与工具，照片包含铜器实物，共同反映西周铸铜生产与相关墓葬出土器物的关系。",
      "description": "展签文字介绍周原出土众多青铜器，李家铸铜作坊发现铜饼原料、车马器、容器、工具陶范，及少量乐器、兵器陶范，并有制模、制范所用的骨铜刻刀、骨针、炉壁残块、坩埚、伞状陶管等遗物；铸铜工艺主要来自商文化，管理者与工匠包含殷遗民。年代为西周（公元前1046-前771年）。器物照片显示2002年扶风齐家墓地M4出土的铜尊、铜卣、铜盒等青铜容器，个别展签文字模糊，确切器名需依实物照片辨认。",
      "significance": "李家铸铜作坊材料直接反映西周时期铜器生产的原料、工具与工艺来源，涉及商文化传统在西周铸铜业中的延续。与齐家墓地M4出土铜器同组陈列，可讨论铸铜生产与贵族用器的联结。展签为概括性介绍，未列具体器物的详细铸造信息，故论证限于展签提供的内容框架内。",
      "viewing_notes": "先读展板文字了解作坊内涵，再看青铜容器照片。展板部分注意铜饼原料、陶范、刻刀与坩埚等不同类别遗物；铜器部分分别观察铜尊、铜卣、铜盒的器形与纹饰，并留意说明文字中提到的“14件”与照片中器物的对应关系。",
      "evidence_note": "展签/展签文字直接支持：遗址性质（李家铸铜作坊）、时代（西周公元前1046-前771年）、发现地点（2002年扶风齐家墓地M4）、展板所述遗物类别（铜饼、陶范、刻刀、骨针、炉壁、坩埚、陶管）。未确认而留空：铜器具体器名（部分展签文字不清，如“铜解”存疑）、各器物尺寸、作坊遗址具体发掘年份与单位编号。",
