      "summary": "这组照片记录了2014年岐山贺家村北凤雏建筑群多个灰坑出土的西周小件器物：金箔、玉片、玉管、骨镞、绿松石、骨铲、海贝与牙器，展示了建筑遗址内出土的多种材质饰件与工具。",
      "description": "展签可辨器物名称包括金箔、玉片、玉管、骨镞、绿松石、骨铲（Bone spade-shaped plow si）、海贝与牙器，年代均为西周（公元前1046-前771年），出土地点涉及2014年岐山贺家村北凤雏建筑群H5、H17、H103、H107、H122、H131等多个灰坑单位。照片中可见金箔呈薄片状，玉片、玉管为玉质小件，绿松石为蓝色小块体，骨镞带锋尖，海贝为贝壳原形，牙器为齿类制品。各器物的具体尺寸与完整度需从实物照片确认。",
      "significance": "这批小件出土于凤雏建筑群的多个灰坑，涵盖贵金属、玉、石、骨、贝、牙等多种材质，可用于讨论西周时期建筑遗址内废弃物的构成及不同材质饰件与工具的使用情况。展签未说明各器物具体功能或与建筑活动的关系，故意义限于作为多材质小件组合的记录。",
