      "summary": "这组照片记录2014年岐山贺家村发现的西周铜轮牙马车及其保护工作，含正射影像与说明展板，展示马车发掘、实验室考古与六年保护修复过程。",
      "description": "展签可辨标题为“贺家铜轮牙马车”，英文标注CHARIOT WITH BRONZE FELLOES AT HEJIA，年代为西周。说明文字记载：2014年在岐山贺家村发现一座西周时期车马坑，内埋一辆青铜轮牙马车，陕西省考古研究院设立专门室内实验室，结合实验室考古与现代文物保护技术进行检测、研究和保护；六年内数十位专家参与方案论证，近百名考古人员参加发掘清理。照片中包含车马坑正射影像。木制车厢与铜轮牙等部件应在影像中可辨。",
      "significance": "贺家铜轮牙马车是西周时期罕见的带铜轮牙马车实物，其发现与保护过程体现了实验室考古方法在车马器研究中的应用。展签着重说明考古与保护结合的工作流程，可作为西周车制研究及实验室考古案例的重要材料，其具体历史意义需依据后续研究结论论证。",
      "viewing_notes": "先读说明展板了解发现经过与工作流程，再看正射影像。影像中注意车轮的铜轮牙结构、车舆与车辕的保存状态。若照片含发掘现场或实验室工作照，可对照展签文字中“室内实验室”“保护复原”等环节理解工作步骤。",
