      "significance": "该组器物属于西周车马坑中的马具组合，为研究西周车马器形制、青铜铸造与绿松石镶嵌工艺提供了实物资料。贺家车马坑出土的铜轮牙马车曾获专门保护与研究，这批马具可作为同类器比较的标本，有助于了解西周贵族车马随葬制度。",
      "viewing_notes": "先看马面的整体轮廓与绿松石镶嵌分布，再对比马镳、马衔的局部细节，注意绿松石片的形状与排列。方形扁平饰与游环可在正面照片中观察其平面形状与环接方式。展签照片可核对名称与出土单位，但游环、马镳等具体对应关系需结合器物编号确认。",
      "evidence_note": "展签/展签文字直接支持：时代（西周公元前1046—前771年）、出土地（2014年周原遗址贺家车马坑K1）、材质（绿松石、铜）、器物名称（嵌绿松石青铜马面、马镳、马衔、方形扁平饰等）。未确认而留空：具体尺寸、每件器物的单独编号与完整器形描述。",
