      "summary": "这组照片记录2014年周原遗址贺家车马坑K1出土的车舆玉器组合、绿松石饰及青铜构件，包括车舆四维玉器、绿松石片与蝉形饰、车轼立柱下青铜龙、车辕首饰、辖軎及（jue）饰等，反映西周车舆装饰的材质与工艺。",
      "description": "展签显示该组为西周（公元前1046年—前771年）遗物，2014年出土于周原遗址贺家车马坑K1。照片可见“玉器组合（车舆四维）”展签，标注为车舆四周装饰的玉器；另有“青铜兽面（车舆后栏）”，为车舆后栏的青铜兽面构件。绿松石片与绿松石蝉为车舆立柱下饰件，绿松石质。青铜龙标注为车轼立柱下饰件。青铜辖軎与辕首饰均嵌绿松石，属于车轴与辕端构件。照片显示器物多件同柜展示，部分为局部特写。",
      "significance": "该组器物出自同一车马坑，组合关系明确，为研究西周车舆结构、装饰方式及玉器、绿松石、青铜多种材质结合工艺提供了直接资料。车舆四维玉器与青铜兽面等构件有助于复原车舆装饰布局，对理解西周贵族用车制度有参考价值。",
      "viewing_notes": "先看玉器组合的整体分布，再对照青铜兽面的位置说明；绿松石蝉与绿松石片可观察其细部形状。青铜龙与辕首饰、辖軎的局部照片应分别查看，注意嵌绿松石的位置与纹饰。展签照片可核对各部件的具体名称与车舆部位。",
      "evidence_note": "展签/展签文字直接支持：时代（西周公元前1046—前771年）、出土地（2014年周原遗址贺家车马坑K1）、器物名称（玉器组合车舆四维、青铜兽面车舆后栏、绿松石片、绿松石蝉、青铜龙车轼立柱下、嵌绿松石青铜辖軎及辕首饰）。未确认而留空：具体尺寸、每件器物的完整形制描述。",
