      "summary": "这组照片记录了2014年周原遗址贺家车马坑K1出土的青铜镞、衡末饰、銮铃与辖饰等车马器。照片显示展签名称、时代与出土地，部分器物嵌绿松石，均为西周时期遗物。",
      "description": "展签显示青铜镞为西周（公元前1046年—前771年）遗物，2014年出土于周原遗址贺家车马坑K1。照片可见青铜镞的锋、翼与铤部。另有嵌绿松石青铜衡末饰，为车衡端饰件，表面镶嵌绿松石；銮铃为青铜质，呈铃形，可能带绿松石镶嵌；辖饰为车辖上的装饰件。因展签文字对部分名称识别不完整，如“嵌绿松石青铜衡末饰”“嵌绿松石青铜銮铃”等，具体器名以展签为准。照片均为器物定妆照或展柜内拍摄。",
      "significance": "该组器物出自贺家车马坑，与铜轮牙马车同坑，为研究西周车马器的完整组合提供了实物。青铜镞与车马饰件共出，可能反映车马坑中的兵器配置或随葬组合。衡末饰、銮铃、辖饰等是复原西周马车结构的重要构件。",
      "viewing_notes": "先看青铜镞的完整形状，对比其翼与铤的细节；再分别查看衡末饰的绿松石镶嵌范围、銮铃的铃体与顶部，以及辖饰的兽面或纹饰。展签照片可核对每件器物的准确定名，避免将嵌绿松石构件名称混淆。",
      "evidence_note": "展签/展签文字直接支持：时代（西周公元前1046—前771年）、出土地（2014年周原遗址贺家车马坑K1）、器物名称（青铜镞、嵌绿松石青铜衡末饰、嵌绿松石青铜銮铃、嵌绿松石青铜辖饰）。未确认而留空：具体尺寸、每件器物的详细形制与完整纹饰描述。",
