      "description": "展签显示青铜铃为西周（公元前1046年—前771年）遗物，2014年出土于周原遗址贺家车马坑K1。照片可见青铜铃为合瓦形或扁圆形铃体，顶部有钮，铃身可能饰有简单的弦纹或素面。由于展签文字对铃身细节识别有限，仅能确认青铜铃的基本形制与出土地。展签英文名称未完整呈现，但中文名称清晰可辨。",
      "significance": "青铜铃常作为马车或仪仗中的响器，贺家车马坑出土的青铜铃为研究西周车马器组合和礼仪用器提供了实例。同一车马坑内出土多种车马器，青铜铃或与马具共同构成车马随葬制度的一部分。",
      "viewing_notes": "先看铃的整体轮廓，注意钮与铃口部的形状；再观察铃身是否有纹饰或铸造痕迹。若有多件铃，可对比大小与形制差异。展签照片可核对时代与出土地点。",
      "evidence_note": "展签/展签文字直接支持：时代（西周公元前1046—前771年）、出土地（2014年周原遗址贺家车马坑K1）、器物名称（青铜铃）。未确认而留空：具体尺寸、铃身纹饰细节、是否成组出土。",
