      "description": "展签显示为文吏进谒图，时代为唐开元十二年（724），1995年出土于渭南蒲城惠庄太子墓。照片可见壁画中文吏的形象，可能包括戴冠、着袍、拱手或持笏的人物。由于展签文字未提供更详细的画面描述，仅能确认图像的题名、时代与出土地。惠庄太子墓为唐代太子墓，其壁画具有较高的等级意义。",
      "significance": "文吏进谒图见于唐代太子墓，为研究唐代太子级墓葬壁画题材与仪礼场景提供了资料。惠庄太子墓的壁画内容可与其他唐墓壁画比较，有助于理解唐代官僚形象与礼仪在墓葬艺术中的表现。",
      "viewing_notes": "先确定壁画中人物的数量与排列，再观察文吏的服饰、冠帽与手势。注意是否持有笏板或作揖姿势。展签提供时代与出土地，但画面具体情节需依赖照片细节。",
      "evidence_note": "展签/展签文字直接支持：时代（唐开元十二年724）、出土地（1995年渭南蒲城惠庄太子墓）、图像名称（文吏进谒图）。未确认而留空：具体尺寸、画面人物数量与细节描述。",
