      "description": "展签显示为女吏图，时代为唐天宝元年（742），2000年出土于蒲城三合村唐惠陵。展签说明墓葬为盛唐时期高等级墓葬，墓主李宪为睿宗之子，追封让皇帝。图像位于第一天井西壁，画面3人分前后面南而立。照片可见南端第1人高1.7米，面如满月，凤目桃腮，上着白色交领小襦衫，下系红色高腰曳地长裙，足穿白色高头履，肩裹白色披帛，双手拢袖拱于胸前。第2人披发单髻，肩搭披帛，袖拢双手拱于胸前。部分人物头部画面已残，左侧似挂鞶囊。",
      "significance": "女吏图见于唐惠陵，该墓为盛唐时期高等级墓葬，墓主李宪身份特殊。图中女吏的服饰与姿态反映了唐代宫廷或贵族家庭中女性侍从的形象，为研究唐代服饰、发式与礼仪提供了具体实例。",
