      "summary": "这组照片记录了高陵马家湾村李晦夫妇墓出土的舞女图壁画，时代为唐永昌元年。图像位于西侧室东壁中部，表现舞女翩翩起舞的姿态，壁画色彩丰富。",
      "description": "展签显示为舞女图，时代为唐永昌元年（689），1995年出土于高陵马家湾村李晦夫妇墓。展签说明李晦为皇室贵胄，深得高宗信任，墓葬由长斜坡墓道、7天井、6过洞、3甬道、3墓室和封土组成，现存壁画有牵马图、列戟图、内侍图、侍女图、舞女图等。图像位于西侧室东壁中部，照片可见舞女梳小髻，细眉凤目，肩部斜搭绿色帛巾，上身着红色窄袖长衫，外套桔黄半臂，下系白色长裙。身体微倾，腰肢轻扭，双臂上举，慢甩小袖。",
      "significance": "舞女图出自李晦夫妇墓，该墓为唐代高等级墓葬，壁画内容丰富。舞女形象展示了唐代舞蹈服饰与姿态，为研究唐代乐舞艺术和贵族生活提供了图像资料。该墓壁画的保存状况也反映了唐代壁画绘制的水平。",
      "viewing_notes": "先看舞女的整体姿态，注意身体倾斜、腰肢扭转与双臂动作；再观察服饰的层次与颜色，如红色窄袖、桔黄半臂、白色长裙与绿色帛巾。展签文字可帮助理解壁画在墓中的位置。",
      "evidence_note": "展签/展签文字直接支持：时代（唐永昌元年689）、出土地（1995年高陵马家湾村李晦夫妇墓）、图像名称（舞女图）、原位置（西侧室东壁中部）、舞女服饰与姿态描述。未确认而留空：具体尺寸、壁画残损情况、舞女身份。",
