      "source_excerpt": "舞女图 | Mural offemale dancer | 唐永昌元年（689） | 1995年高陵马家湾村李嗨夫妇墓 | 李嗨为皇室贵胃，生前身居高位，深得高宗信任，葬于武则天永昌元年 | （689）。墓葬残长46.3米，由长斜坡墓道、7个天井、6个过洞、3条甬道、呈 | “品”字形排列的3个墓室和墓上封土组成。现存的壁画内容有牵马图、列戟图、 | 内侍图、侍女图、舞女图等。 | 图像位于西侧室东壁中部。舞女梳小医，细眉凤目，肩部斜搭一绿色帛 | 上身着红色窄袖长衫，外套桔黄半臂，下系白色长裙。身体微倾，腰肢轻扭，双 | 臂上举，慢甩小袖，从右腰部上搭于左肩的长帛随风轻拂，给人以舞兴正醋之 | 感 大梁墓地北朝壁画墓M | 用发掘，距统万 | 为斜坡墓道单 | 1时期的统万城 | 刷白灰浆水绘 | 宗教气氛浓郁 | 日月星辰和 | 承。",
