      "summary": "这组照片记录了旬邑百子村东汉墓出土的亭长女儿图壁画，时代为东汉。图像位于墓室东边侧室墓壁，表现“亭长”的女儿站于树下，属于汉墓中常见的人物图像。",
      "description": "展签显示为亭长女儿图，时代为东汉（25—220年），2000年出土于旬邑百子村东汉墓。图像位于墓室东边侧室墓壁。照片可见一位女性形象站于树下，应为“亭长”的女儿。展签文字说明“亭长”另绘于墓门内侧的甬道，束额皂衣、佩剑持盾，左右把守墓葬门。此类画像在汉墓中经常见到，有学者将这一题材与镇墓文中的“门亭长”联系起来。画面具体的人物服饰与树形需从照片中观察。",
      "significance": "亭长女儿图为汉墓中的人物题材，与墓门内侧的亭长形象相呼应，为研究汉代墓葬壁画中的人物组合与镇墓观念提供了实例。女儿站于树下的场景可能具有象征意义，需结合更多同类资料比较。",
      "viewing_notes": "先看人物与树的位置关系，注意人物的站姿、服饰与发式；再观察树的形态与枝叶画法。由于壁画可能有残损，应注意画面边缘的完整性。展签提供时代与出土地，但树的种类与人物细节需照片确认。",
      "evidence_note": "展签/展签文字直接支持：时代（东汉25—220年）、出土地（2000年旬邑百子村东汉墓）、图像名称（亭长女儿图）、原位置（墓室东边侧室墓壁）、人物描述（亭长女儿站于树下）。未确认而留空：具体尺寸、树的种类、人物的完整服饰细节。",
