      "source_excerpt": "车马出行图 | Mural of chariot and horse | 新莽一东汉（公元9-220年） | 2003年定边郝滩四十里铺东汉墓群 | 图像位于墓室东壁，是汉代常见的壁画题材，多用来表现墓主人生前的身份 | 地位或仕途经历。画面形象简约而极具张力，马嘴喷张、毛竖立、前蹄高举， | 一位绿衣女主人安坐车中，身旁一黑衣男子驾车前行，有三只鸿雁在天空一字排 | 开飞翔。壁画底色以青绿色（经检测分析为绿士）为衬托，车舆和马匹的毛都 | 以黑色表现，搭配白、红、蓝等颜料绘制不同内容，整体上呈现热烈愉悦的装饰 | 氛围。从车轮的表现手法上来看，战国至汉初的车轮往往仅见一轮，西汉中期始 | 见两轮，而这幅画面上里侧一轮微高并微前于外轮，体现出汉代绘画空间中“透 | 视”意识的进步。 人。",
