      "description": "展签显示为彩绘陶楼，时代为西晋（266—317年），2002年出土于西安长安区陕西师范大学新校区西晋墓。照片可见陶楼为多层楼阁式建筑模型，外表面施有彩绘。展签文字说明“除了宫室壁画外，大户人家也普遍绘制壁画。考古发掘墓葬出土的陶楼建筑模型，有的外表面会以彩绘装饰模仿壁画。”陶楼的层数、檐部结构与彩绘图案需从照片中具体观察。",
      "significance": "彩绘陶楼作为墓葬明器，反映了西晋时期的建筑形制与装饰手法。其外壁彩绘模仿壁画，为研究墓葬壁画与建筑模型之间的关系提供了实物。陶楼模型也是了解当时地面建筑结构的重要参考。",
      "viewing_notes": "先看陶楼的整体形状与层数，注意檐部、斗拱与门窗的位置；再观察外壁彩绘的残存情况，辨别颜色与图案。由于陶楼为立体模型，应结合多角度照片从正面、侧面观察。",
      "evidence_note": "展签/展签文字直接支持：时代（西晋266—317年）、出土地（2002年西安长安区陕西师范大学新校区西晋墓）、器物名称（彩绘陶楼）、材质（陶）。未确认而留空：具体尺寸、层数、彩绘图案的具体内容。",
