      "summary": "这组照片记录了口簧及其对比展示，包括现代口簧与石峁出土口簧。展签说明文字指出出土于皇城台的口簧被赋予沟通人神、祭祀先祖的功能，并配有口簧基本结构与使用方法对比图。照片可用于观察口簧的形制与演奏方式说明。",
      "description": "照片中可见现代口簧与出土口簧的对比展示，展签文字说明出土于皇城台的口簧具有沟通人神、祭祀先祖的推测功能，并描述其演奏时通过口腔与乐器结合发出“呷呷”“嗡嗡”声，可模仿动物音律或产生仪式感旋律。展签另配有口簧基本结构图，标注簧舌、拉孔、簧鞘等部件，以及石峁口簧与现代口簧的使用方法对比。出土口簧的具体时代与材质在现有展签文字中未直接标出，仅可从展签语境推断与皇城台相关。",
      "significance": "口簧作为小型体鸣乐器，其出土于皇城台的记录为讨论龙山时期或相关阶段的乐器形态与可能的社会功能提供了考古实物资料。展签说明中关于其祭祀、通神功能的表述属于展陈方的解释性内容，可作为学术讨论的参考，但需与具体出土背景和器物学分析结合使用。",
