      "summary": "这组照片记录了龙山晚期至夏代早期的陶球哨与骨管哨，展签显示二者均出土于2017年神木石峁遗址皇城台。照片可见陶质球状哨与骨质管状哨的外观，是石峁遗址出土小型吹奏乐器的记录。",
      "description": "展签可辨的名称与信息为“陶球哨”与“骨管哨”，时代均为龙山晚期至夏代早期（距今4300-3800年），出土于2017年神木石峁遗址皇城台。照片可见陶球哨呈球形或近球形，表面或有小孔；骨管哨呈管状，中空，一端或两端有吹孔。两种哨类均以小型乐器形态呈现，具体尺寸、孔径与吹奏方式需由实物或详细照片确认。",
      "significance": "陶球哨与骨管哨作为龙山晚期至夏代早期的吹奏乐器标本，为讨论该时期乐器的材质选择、制作工艺与使用场合提供了实物资料。两种哨类在同期遗址中较为少见，适合与石峁遗址其他出土乐器及周边区域的相关发现进行类型比较与功能分析。",
      "viewing_notes": "先看有展签的照片确认名称、时代与出土信息，再分别观察陶球哨与骨管哨的形态差异。注意陶球哨表面的孔位与数量，以及骨管哨的管径、长度和吹口处理；若有多角度照片，比较两种哨类的制作痕迹与使用磨损。",
      "evidence_note": "展签/展签文字直接支持的字段：title（陶球哨、骨管哨）、period（龙山晚期至夏代早期距今4300-3800年）、findspot（2017年神木石峁遗址皇城台）、category（乐器）、material（陶、骨）。未确认而留空的字段：dimensions；description中孔位、管径等为照片观察所得。",
