      "id": "artifact-090",
      "index": 90,
      "start": 285,
      "end": 286,
      "title": "甲骨与岐山周公庙遗址",
      "category": "遗址资料、甲骨",
      "period": "公元前12世纪—前771年（遗址年代）",
      "dimensions": "",
      "findspot": "",
      "material": "甲骨",
      "theme": "西周甲骨、遗址概况",
      "summary": "这组照片记录了岐山周公庙遗址的概况与出土甲骨资料，展签文字说明遗址位置、面积、商周时期遗存分布及甲骨出土情况。另一个展板列出遗址年代、发掘时间、地点与发掘单位，并标注2008年度全国十大考古新发现等荣誉。",
      "description": "展签文字说明遗址位于岐山县城北的凤凰山南麓，面积约4.5平方千米，其中商周时期遗存达3.7平方千米，发现了夯土建筑基址、壕沟、铸铜及制陶作坊、墓地等遗存。甲骨集中发现于庙王村西和祝家巷北，共出土8000余件，种类以卜甲为主、卜骨较少，龟腹甲居多、背甲少见；有字与无字兼有，以无字居多。背面钻凿，卜甲多为长凿方钻，卜骨多猫眼钻。遗址项目信息栏标注遗址年代为公元前12世纪—前771年，发掘时间为2004—2011年，发掘地点为宝鸡市岐山县凤鸣镇，发掘单位为陕西省考古研究院、北京大学、宝鸡市考古研究所。荣誉奖项包括2008年度全国十大考古新发现与2007—2008年度田野考古奖一等奖。",
      "significance": "岐山周公庙遗址作为出土大量西周甲骨的遗址，其出土甲骨达8000余件且字数为全国西周甲骨文字最多者，为研究西周甲骨占卜制度、文字内容与聚落结构提供了重要材料。展签中关于遗址范围、遗存种类与甲骨分布的信息可作为讨论遗址性质与功能分区的依据。",
      "viewing_notes": "先看甲骨实物照片，注意卜甲的钻凿形态与腹甲、背甲的区别，再对照遗址概况展板了解出土位置与数量。最后看项目信息栏，确认遗址年代、发掘时间与发掘单位；若甲骨照片与遗址平面图并列，应结合图上位置理解出土背景。",
      "evidence_note": "展签/展签文字直接支持的字段：title（甲骨与岐山周公庙遗址）、category（遗址资料、甲骨）、period（遗址年代公元前12世纪—前771年）、findspot（岐山县城北凤凰山南麓；庙王村西与祝家巷北）、material（甲骨）、theme（西周甲骨、遗址概况）。未确认而留空的字段：dimensions、具体甲骨编号；description中遗址面积、出土数量、钻凿形态等均直接采自展签文字。",
