      "source_excerpt": "甲骨 | 在整治好的龟甲背面制作钻凿 | ORACLE BONES | 甲骨集中发现于庙王村西和祝 | 家巷北，共出土8000余件。种类 | 以卜甲为主，卜骨较少；龟腹甲居 | 多，背甲少见。有字、无字兼有， | 以无字居多。背面钻凿，卜甲大都 | 为长凿方钻，卜骨多猫眼钻。 | 在钻凿内施灼 | 才（在）口毫卜，癸卯，又尚口大离。 | 王其乎腹（摸）制（薄）姑来事于復口召削 | (薄）姑，区（使）亡答。 | 2004年岐山周公庙遗址庙王村西H11 遗址位于岐山县城北的凤凰山南麓，面积约4.5 | 中商周时期遗存达3.7平方千米。发现了分土建筑基址、 | 壕沟、铸铜及制陶作坊、墓地等遗存。遗物种类丰富，尤 | 为突出。出土了大量包含周初重要人物与地理的刻辞甲 | 2500余字，为全国发现西周甲骨文字最多的遗址。发据 | 富的层位关系与实物资料，由此建立了该遗址商周时期老 | 的分期谱系，厘清了商周时期的聚落结构，判断其聚落性 | 岐山周公庙 | 公采邑”。 | 遗址 | 项目信息 | THE‘DUKE OFZHOU | 遗址年代：公元前12世纪一前771年 | TEMPLE'ATQISHAN | 发掘时间：2004-2011年 | 发掘地点：宝鸡市岐山县凤鸣镇 | 发掘单位：陕西省考古研究院、北京大学、宝鸡市考古研究所 | 荣誉奖项 | 2008年度全国十大考古新发现 | 2007-2008年度田野考古奖一等奖。",
