      "category": "青铜器、陶器、骨器、蚌器",
      "period": "西周（公元前1046—前771年）",
      "dimensions": "",
      "findspot": "2016年西安长安区斗门街道花园村M12（铜器与陶器）；2016年西安长安区斗门街道花园村H242、H241（骨板、蚌刀）",
      "material": "铜、陶、骨、蚌",
      "theme": "西周随葬品与灰坑遗物",
      "summary": "这组照片记录了西安长安区斗门街道花园村遗址出土的一批西周遗物，包括弦纹鼎、铜戈、云纹镳、兽首辖、陶瓿、陶器盖等墓葬出土品，以及骨板、蚌刀等灰坑出土遗物。展签显示时代为西周，铜陶器出土于M12，骨蚌器出土于H242或H241。",
      "description": "展签可辨的器物包括弦纹鼎、铜戈（残）、云纹镳、兽首辖、陶瓿、陶器盖等，时代为西周（公元前1046—前771年），出土于2016年西安长安区斗门街道花园村M12。另一组展签标有骨板、蚌刀（另有骨锤等），时代同为西周，出土于2016年西安长安区斗门街道花园村H242或H241。照片中各器物按类别陈列，铜器可见弦纹鼎的腹部弦纹带与双耳，铜戈已残，云纹镳表面饰云纹，兽首辖一端有兽首形象；陶瓿与陶器盖呈灰陶质地。骨板与蚌刀为工具类遗物，具体形态需由照片细部辨认。",
      "significance": "该组遗物包含墓葬随葬铜陶器与灰坑出土骨蚌器，反映了同一遗址西周时期墓葬与灰坑遗物的不同组合。弦纹鼎、铜戈、车马器等为研究西周时期墓葬随葬品的器类组合提供标本，骨板、蚌刀等工具类遗物则可用于讨论遗址内部生产活动与废弃物处理方式。",
      "viewing_notes": "先按展签分组确认墓葬出土铜陶器与灰坑出土骨蚌器的区别，再逐件观察铜器的纹饰带与残断部位。注意弦纹鼎的腹部弦纹是否连续、铜戈残断位置、云纹镳的纹饰布局，以及兽首辖的兽首朝向；骨板与蚌刀应比较其表面加工痕迹与刃部形态。",
      "evidence_note": "展签/展签文字直接支持的字段：title所列器物、period（西周公元前1046—前771年）、findspot（2016年西安长安区斗门街道花园村M12；H242、H241）、category（青铜器、陶器、骨器、蚌器）、material（铜、陶、骨、蚌）。未确认而留空的字段：dimensions；description中兽首形象、弦纹布局等为照片观察所得；骨锤虽出现于展签文字但未列入题名，已在description中提及。",
