      "material": "铜",
      "theme": "四耳簋、青铜礼器",
      "summary": "这组照片记录了宝鸡石鼓山商周墓地M4出土的四耳簋，展签显示时代为商代晚期至西周早期，由石鼓山考古队收藏。照片包含器物的整体与局部视角，可见簋身四耳结构及其纹饰，是观察该器形与装饰的珍贵资料。",
      "description": "展签可辨的信息为“四耳簋”，英文标注为“Bronze ritual food vessel (gui) with four handles”，时代为商代晚期至西周早期，出土于2013年宝鸡石鼓山商周墓地M4，收藏单位为石鼓山考古队。照片可见簋为圆形腹、圈足或方座结构，口部两侧及前后共设四耳，耳部突出于器身。器表以浮雕或线刻方式饰有纹饰带，耳部与腹部的具体纹样需由不同角度照片确认。器物表面呈现青铜器常见的锈色，整体保存状况良好。",
      "significance": "四耳簋属于商代晚期至西周早期青铜礼器中的盛食器，其四耳结构在同类簋中具有形态上的辨识度。该器出土于宝鸡石鼓山商周墓地M4，为研究该墓地青铜器的器类组合、装饰风格与区域特征提供了实物比较资料，尤其适合与关中地区同期墓葬出土的青铜簋进行类型学分析。",
      "viewing_notes": "先看整体照片确认簋的器形与四耳的分布位置，再看局部照片观察耳部与器腹的纹饰衔接。比较不同角度下耳部的凸起程度与腹部纹饰带的变化，注意圈足或方座的形状以及器表锈色与修补痕迹；若展签照片可见，应核对器物编号。",
      "evidence_note": "展签/展签文字直接支持的字段：title（四耳簋）、period（商代晚期至西周早期）、findspot（2013年宝鸡石鼓山商周墓地M4）、category（青铜器）、material（铜）、theme（四耳簋、青铜礼器）。未确认而留空的字段：dimensions；description中器形与纹饰细节为照片观察所得。",
