      "description": "展签可辨的信息为“牺尊”，英文标注为“Bronze animal-shaped wine vessel (zun)”，时代为商代晚期至西周早期，出土于2013年宝鸡石鼓山商周墓地M4，收藏单位为石鼓山考古队。照片可见器物整体呈动物形状，头部、身躯与四肢均有表现，背部或顶部设有注口或器口。器表饰有纹样，动物细部如耳、角、尾等特征需由多角度照片辨认。青铜表面可见锈色与局部保存差异。",
      "significance": "牺尊作为商代晚期至西周早期的动物形青铜酒器，其出土于宝鸡石鼓山商周墓地M4，为研究该时期动物形青铜器的造型传统、铸造工艺与随葬组合提供了比较材料。动物形酒器在商周青铜器中具有特殊地位，可作类型学与图像学分析的实物标本。",
      "viewing_notes": "先看整体照片确认动物的种类特征与器口位置，再看头部与躯体的局部照片，观察角、耳、蹄等细部表现。比较不同角度下器表的纹饰分布与铸造痕迹，注意背部器口与注口的对应关系以及四肢与器身的连接方式。",
