      "summary": "这组照片记录了宝鸡石鼓山商周墓地M4出土的附耳龙纹鼎，展签显示时代为商代晚期至西周早期，由石鼓山考古队收藏。照片可见鼎的双附耳结构与器腹龙纹装饰，是观察商周之际青铜鼎形制与纹饰的资料。",
      "description": "展签可辨的信息为“附耳龙纹鼎”，英文标注为“Bronze ritual tripod cauldron (ding) with folded handles and dragon decoration”，时代为商代晚期至西周早期，出土于2013年宝鸡石鼓山商周墓地M4，收藏单位为石鼓山考古队。照片可见器形为圆腹鼎，口部两侧设有附耳，耳部折向上方或外侧，腹下有三足。器腹表面饰有龙纹，龙形以浮雕或线刻方式呈现，纹饰带的位置与单元需由局部照片确认。器表青铜锈色明显，部分区域纹饰因锈蚀或残损而模糊。",
      "significance": "附耳龙纹鼎为商代晚期至西周早期青铜鼎的重要类型，其附耳与龙纹的组合可作为讨论该时期鼎类器形演变与纹饰传统的比较标本。出土于宝鸡石鼓山商周墓地M4，为分析该墓地青铜器的铸造工艺、装饰风格与随葬组合提供了实物依据。",
      "viewing_notes": "先看整体照片确认鼎的器形、附耳的朝向与三足的形态，再看器腹龙纹的局部特写，观察龙纹的构图单元与线条深浅。比较不同角度下耳部与口沿的关系，以及腹部纹饰带与足部的衔接；注意鼎内壁或底部是否可见铸造痕迹。",
