      "description": "展签可辨的信息为“青铜簠”，英文标注为“Bronze food vessel (fu)”，时代为商代晚期至西周早期，出土于2013年宝鸡石鼓山商周墓地M4，收藏单位为石鼓山考古队。照片可见器物呈长方形或方形，由器身与盖两部分组成，盖与身形状相近，或可却置。器表饰有纹饰带，具体纹样与布局需由多角度照片确认。青铜表面呈现锈色，器物整体形态保存较为完整。",
      "significance": "青铜簠作为商周时期盛食器，其出土于宝鸡石鼓山商周墓地M4，为研究商代晚期至西周早期簠类器物的形制、纹饰与随葬组合提供了实物资料。簠在商周青铜器中的出现与演变具有类型学意义，可与关中地区同期墓葬出土青铜簠进行比较研究。",
      "viewing_notes": "先看整体照片确认簠的方形轮廓与盖身关系，再看器表纹饰的局部照片，观察纹饰带的位置与单元结构。比较盖与身的纹饰是否对应，并注意器口、圈足或四足的形态；若有多角度照片，应观察器身内壁与外底的铸造痕迹。",
