      "description": "展签可辨名称“木俑”，英文“Wooden figure”，属西周晚期，2007年韩城梁带村遗址M502出土，材质标为“木”。照片可见木俑的直立形态，头部、躯干与四肢比例简洁，表面有木质纹理与裂痕，保存状态一般。因缺乏全景对比照片，尚无法判断其原始高度与具体姿态细节，但可确认其为立体圆雕状人形木制品。",
      "significance": "该木俑属于西周晚期墓葬出土的丧葬用俑，是研究当时墓葬随葬组合与木雕工艺的实物资料。其出土于韩城梁带村遗址，对了解芮国贵族丧葬习俗有一定参考价值。可作为同墓地出土青铜礼器之外的材质补充，用于比较同期木俑的造型与制作方法。",
      "viewing_notes": "先看展签确认名称与时代，再观察木俑整体轮廓，注意头部、躯干与四肢的比例。随后比较正面与侧面照片中的厚度与曲度，局部照片可查看表面刀痕或裂痕，判断制作方式与保存状况。",
