      "summary": "这组照片记录了一组春秋早期的组玉佩饰与多件随身玉饰，均出土于2006年韩城梁带村遗址M19和M26。七璜联珠组佩由7件玉璜和728颗红玛瑙珠串联而成，另见腕饰、臂饰、项饰、玉握、玉鱼、玉鸟等。",
      "description": "展签可辨名称包括“七璜联珠组玉佩”“组玉佩饰”“右手腕饰”“左手腕饰”“臂饰”“玉管项饰”“玉牌项饰”“玉握饰”“玉贝”“人形玉佩”“玉玦”“玉鱼”“玉鸟”“玉牛”“玉兽面”“玉璧”等，时代多标“春秋早期”，部分标“西周晚期”或“商代晚期至春秋早期”。出土地涉及M19、M26，部分标M29、M15。照片可见组玉佩的璜与玛瑙珠串联结构，以及各件玉饰的形制，部分玉器表面有纹饰或沁色。",
      "significance": "七璜联珠组佩由7件玉璜和728颗红玛瑙珠构成，展签说明“达到了国君的配置级别”，是研究西周晚期至春秋早期高级贵族用玉制度与组佩组合的重要实例。M19和M26为M27芮国国君的两位夫人墓，随葬玉器丰富，对了解芮国贵族女性墓的随葬组合有直接参考价值。",
      "viewing_notes": "先看展签确认七璜联珠组佩的璜数、珠数与串联结构，再依次观察腕饰、臂饰、项饰、握饰等位置性玉饰。组内不同局部照片可比较玉料颜色、纹理与加工工艺，注意区分不同墓葬出土的器物。",
      "evidence_note": "展签/展签文字直接支持：名称、时代“春秋早期”/部分“西周晚期”、出土地“2006年韩城梁带村遗址M19/M26”、材质“玉、玛瑙”、七璜728珠的结构说明。未确认而留空：具体尺寸、部分器物的准确墓葬编号（M29/M15等展签文字有歧义）、各件玉器的精确用途。",
