      "summary": "这组照片记录了一件春秋早期的龙纹盉，出土于2006年韩城梁带村遗址M26。照片展示盉的整体造型、提梁、流与盖部龙纹，可观察其器形与纹饰细节。",
      "description": "展签可辨名称为“龙纹盉”，英文“Bronze spouted wine vessel (he) with dragon decoration”，属春秋早期，2006年韩城梁带村遗址M26出土，材质标“铜”。照片可见盉的圆腹、带流与提梁，盖顶或器身饰龙纹，可能为浮雕或线刻。局部照片可辨认龙首、龙身与地纹，但无法确认是否有铭文。",
      "significance": "龙纹盉出土于韩城梁带村遗址M26，属春秋早期芮国贵族用器，形制为带流与提梁的盉，是水器或酒器组合的成员。龙纹装饰具有时代特征，可用于比较春秋早期青铜盉的造型演变与龙纹母题，也可补充芮国青铜器群的研究资料。",
      "viewing_notes": "先看展签确认名称、时代与出土地，再观察盉整体轮廓，注意流、提梁与足的连接方式。比较正、侧、顶视角照片，可判断提梁与盖的曲度、流的长短，局部图像可细看龙纹的线条、眼睛与鳞片，注意是否有铸造范线。",
      "evidence_note": "展签/展签文字直接支持：名称“龙纹盉”、时代“春秋早期”、出土地“2006年韩城梁带村遗址M26”、材质“铜”、纹饰“龙纹”。未确认而留空：尺寸、具体器高、是否有铭文、提梁结构细节（链式或条式）。",
