      "theme": "仲姜壶与芮国国君墓随葬品",
      "summary": "这组照片记录了一件名为“仲姜壶”的青铜壶，以及2006年韩城梁带村遗址M27出土的一组随葬器物。M27随葬品包括金饰件、玉器、铁戈等，展签标为春秋早期。",
      "description": "展签可辨“仲姜壶，Bronze wine vessel (hu) with inscription of 'Zhong Jiang'”，属春秋早期，2006年韩城梁带村遗址M26出土。另有展签“M27随葬器物”，包括“兽面金龙”“方形金环”“圆形金泡”“金丝圈”“素面双龙金环”“镂空双龙金环”“三角形金饰”“金牛首衔环”“镂空螭纹金饰”“玉韘”“金韘”“铁戈”等，均标春秋早期及2006年韩城梁带村遗址M27。照片可见仲姜壶的壶体、长颈、贯耳与盖，以及M27各件金饰的造型与玉韘、铁戈的形态。",
      "significance": "仲姜壶铭文表明器主为“仲姜”，出土于M26，与M27芮公墓形成对应，对研究芮国婚姻关系与社会结构具有重要意义。M27随葬的金器、玉韘、铁戈等组合反映了春秋早期芮国国君墓的财富与军事装备，铁戈的出土对探索早期铁器使用有参考价值。",
      "viewing_notes": "先看仲姜壶展签确认铭文与出土地，再观察壶体各部位比例。随后转向M27随葬器物群，逐件比较金饰的造型差异，注意镂空与素面工艺的对比。最后观察玉韘与铁戈的形态，可参照展签编号与英文说明。",
      "evidence_note": "展签/展签文字直接支持：名称“仲姜壶”“M27随葬器物”、时代“春秋早期”、出土地“M26/M27”、材质“铜、金、玉、铁”、器物名称“兽面金龙”“方形金环”“镂空双龙金环”“铁戈”等。未确认而留空：尺寸、各件金饰的具体重量或用途、仲姜壶铭文全文、铁戈的完整形制。",
