      "description": "展签可辨名称为“梯形牌组玉佩”，英文“Neck ornament with jade plaques”，属西周晚期，2009年韩城梁带村遗址M300出土。另有一名“玉牌项饰”。材质标注有“玉”“煤晶”“玛瑙”“贝”等，但展签文字中“煤玛”“精璃”等字可能为“煤精”与“玛瑙”的误读。照片可见梯形玉牌位于中心，四周串联多色珠饰，包括红色玛瑙珠、深色煤精珠与贝饰，组成对称结构的组玉佩。",
      "significance": "该组玉佩属于西周晚期高级贵族随葬玉器，出土于韩城梁带村遗址M300。梯形牌与串珠的组合形式对研究西周晚期组玉佩的结构演变具有参考价值，可用于比较同期其他墓地出土的同类组玉佩，进而讨论玉器使用制度与地域风格。",
      "viewing_notes": "先看展签确认名称与出土地，再观察梯形玉牌的形状、厚度与表面纹饰。随后注意串珠的颜色、大小与排列顺序，比较不同材质的珠子在组佩中的位置，可对照“玉牌项饰”名称判断其佩戴功能。",
      "evidence_note": "展签/展签文字直接支持：名称“梯形牌组玉佩”“玉牌项饰”、时代“西周晚期”、出土地“2009年韩城梁带村遗址M300”、材质标“玉/煤精/玛瑙/贝”（展签文字有歧义）。未确认而留空：具体尺寸、珠数、玉牌纹饰细节；材质名称需以实物核对。",
