      "description": "展签可辨名称为“晋妀匜”，英文“Bronze pouring vessel (yi) with inscription of 'Jin Ji'”，属西周晚期，2009年韩城梁带村遗址M300出土。照片可见匜的槽状流、兽首鋬、深腹与四足或圈足，器身可能有纹饰带。局部照片未能显示铭文具体字形，但展签明确存在“晋妀”铭文。",
      "significance": "晋妀匜与晋妀盘同铭配套，属西周晚期水器组合，出土于韩城梁带村遗址M300。铭文“晋妀”对探讨器主身份、族属及芮国与晋国关系有重要价值。作为有铭匜，可用于比较青铜匜的流鋬形制与铭文位置。",
