      "description": "展签可辨名称“编钟”，英文“Set of bronze bells (bianzhong)”，时代为“春秋（公元前770-前476年）”，出土于2018年澄城刘家洼遗址东1区M1。展签文字未提供材质标注，但据名称应为铜质。照片内容大多未见可辨展签文字文字，推测为编钟的正面、侧视或局部照片，可观察钟体形状、枚与篆带，但具体细节需从图像确认。",
      "significance": "编钟出土于澄城刘家洼遗址东1区M1，属春秋时期芮国遗存。成套编钟是高级贵族礼乐制度的象征，可用于研究刘家洼遗址的等级与礼乐制度，以及春秋时期青铜乐钟的制造与音律安排。照片资料有助于记录编钟的组合状态与个体特征。",
      "viewing_notes": "首先确认展签中编钟的件数与遗址信息，然后观察钟体的整体轮廓，注意甬钟或钮钟的类型、钟枚分布、篆带纹饰。组内不同照片可比较各钟的大小递减与角度，观察是否有悬挂痕迹。",
      "evidence_note": "展签/展签文字直接支持：名称“编钟”、时代“春秋（公元前770-前476年）”、出土地“2018年澄城刘家洼遗址东1区M1”。材质未在展签文字中标示，依据名称推断为铜，但严格而言“未确认而留空”。未确认而留空：尺寸、件数、钟体类型、纹饰、保存状况。",
