      "description": "展签可辨名称为“芮公鼎”，英文“Bronze ritual tripod cauldron (ding) with inscription of 'Rui Gong'”，时代为“春秋（公元前770－前476年）”，材质标“铜”，出土于2017年澄城刘家洼遗址东1区M3。照片可见鼎的圆形腹、双耳与三足，器身可能有纹饰带，但展签文字未给出。铭文“芮公”应为铸刻在器壁或内底，照片中未清晰显示具体字形。",
      "significance": "芮公鼎铭文直接提到“芮公”，为确认刘家洼遗址的芮国属性及国君墓葬提供了关键证据。此鼎对研究春秋时期芮国政治、青铜器铸造及铭文格式具有重要价值，可作为有铭芮国青铜器的标型器。",
      "viewing_notes": "先看展签确认铭文“芮公”与该遗址信息，再观察鼎的耳、足、腹比例与纹饰带位置。局部照片可尝试找铭文铸刻区域，但若模糊需说明。比较鼎的器壁厚度与锈蚀程度，判断保存状态。",
      "evidence_note": "展签/展签文字直接支持：名称“芮公鼎”、时代“春秋（公元前770-前476年）”、材质“铜”、出土地“2017年澄城刘家洼遗址东1区M3”、铭文存在“芮公”。未确认而留空：尺寸、鼎足形状、纹饰细节、铭文具体位置与内容全貌。",
