      "summary": "这组照片记录了一件春秋时期的小型龙纹罍和一件窃曲纹罐。龙纹小罍出土于2009年韩城梁带村遗址M300，窃曲纹罐出土于2006年韩城梁带村遗址M27，两者均属青铜容器。",
      "description": "展签可辨名称有“龙纹小罍”，英文“Miniature bronze wine vessel (lei) with dragon decoration”，以及“窃曲纹罐”，英文“Bronze jar with interlinked curves decoration”，时代均为“春秋（公元前770一前476年）”。龙纹小罍出土地为2009年韩城梁带村遗址M300，窃曲纹罐出土地为2006年韩城梁带村遗址M27。照片可见小罍的带盖圆腹、双耳与圈足，表面饰龙纹；窃曲纹罐整体较小，腹部饰窃曲纹带，可能无耳或带小耳。",
      "significance": "两件小型青铜容器分属不同墓葬，体现了春秋时期芮国贵族随葬品的多样性。龙纹小罍可补充小型酒器的资料，窃曲纹罐则提供了窃曲纹在小件容器上的应用实例。二者可用于比较同类器的用途差异与地域共性。",
      "viewing_notes": "先分别确认两件器物的展签，再观察龙纹小罍的盖、耳、足结构与龙纹走向；随后观察窃曲纹罐的腹部曲线与纹饰密度。注意两件器物的尺寸比例，可在照片中寻找标尺或展签上的编号。",
      "evidence_note": "展签/展签文字直接支持：名称“龙纹小罍”“窃曲纹罐”、时代“春秋（公元前770-前476年）”、出土地“M300/M27”、材质“铜”（名称暗示青铜，但展签文字未直接标“铜”）。未确认而留空：尺寸、具体形制参数、窃曲纹罐的耳部与底足形态。",
