      "description": "展签可辨名称为“变形兽纹小罐”，英文“Miniature bronze jar with stylized animal decoration”，时代为“春秋（公元前770一前476年）”，出土于2009年韩城梁带村遗址M300。照片可见罐体较小，圆腹、口沿外侈，底部可能有圈足或小平底。器表饰变形兽纹，纹样抽象而具图案化，可能为线刻或浮雕。局部照片可观察纹饰的连贯性与刻工。",
      "significance": "该罐为小型青铜容器，属于梁带村M300随葬品组合中的小件器物，对了解春秋时期青铜器的小型化、功能分化以及纹饰的图案化发展具有参考价值。此类“变形”纹饰常与地域风格或工艺简化相关，可用于比较。",
