      "description": "展签可辨名称为“象牙削盒”，英文“Ivory box for scraping knife”，时代为“春秋（公元前770－前476年）”，出土于2006年韩城梁带村遗址M19。照片可见盒体呈扁长方体或圆角矩形，表面有象牙特有的纹理，局部可能有榫接或开合痕迹。器表是否刻有纹饰或文字，展签文字未提供，需从图像确认。",
