      "viewing_notes": "先看展签确认名称、时代与出土地，再观察盒的整体形状与表面纹理。注意盒盖与盒身的接合处，局部照片可查看是否有子母口或镶嵌物。比较不同视角的照片判断盒的厚度与长宽比例。",
      "evidence_note": "展签/展签文字直接支持：名称“象牙削盒”、时代“春秋（公元前770-前476年）”、材质“象牙”、出土地“2006年韩城梁带村遗址M19”。未确认而留空：尺寸、具体结构（盖/底分离或一体）、表面是否有纹饰或铭文。",
