      "description": "展签可辨名称为“秦始皇铜诏版（残）”，英文“Bronze edict tablet of the Emperor Qinshihuang (fragment)”，时代为“秦 (公元前221年)”，出土于1962年咸阳渭城区长陵车站金属窖藏。额外照片显示释文及相关说明，但展签文字中释文内容模糊，可能涉及度量衡诏书文字。照片可辨铜版残片，表面有刻铭文字，锈蚀与土锈覆盖部分字口。",
      "significance": "铜诏版是秦统一度量衡的直接实物证据，刻有秦始皇诏文，对研究秦朝法律制度、度量衡统一及文字标准具有重要意义。此残件出土于咸阳长陵窖藏，反映了秦中央权力的实施方式，可用于同批窖藏出土铜诏版的比较。",
      "viewing_notes": "先看展签确认名称、时代与出土地，再观察铜版残片的形状与边缘断裂处。随后细看表面刻铭，注意字口深度与书风，可对照释文照片逐字辨认。比较不同角度照片判断残片原尺寸与缺失部分。",
      "evidence_note": "展签/展签文字直接支持：名称“秦始皇铜诏版（残）”、时代“秦（公元前221年）”、出土地“1962年咸阳渭城区长陵车站金属窖藏”。未确认而留空：尺寸、残存字数、具体诏文内容、铭文是否完整或已残断。",
