      "summary": "这组照片记录了一件秦二世时期的铜诏版，为残片。照片包括器物正面和局部特写，展签可辨读出诏文内容，涉及秦始皇统一度量衡的历史以及秦二世重申此诏令的记载。器物出土于咸阳渭城区长陵车站的金属窖藏。",
      "description": "展签显示此物名为“秦二世铜诏版”，年代为秦（公元前209年），出土地点为1982年咸阳渭城区长陵车站金属窖藏。照片可见铜诏版为残片，表面刻有文字。局部照片中可辨读出部分诏文，如“法度量，尽始皇帝为之”“元年，制诏丞相斯、去疾”“有刻辞焉，今袭号”“如后嗣为之者，不称成功盛德”等内容，并有“释文”标注辅助阅读。文字刻划清晰，保存状况可从照片中直接观察。",
      "significance": "该铜诏版是秦代统一度量衡制度的实物证据。诏文内容直接引用秦始皇诏书并由秦二世重申，反映了秦代中央政令的延续与传达方式。此类有铭铜诏版对研究秦代行政制度、文字及度量衡政策具有比较价值。",
      "viewing_notes": "观看时可先看整体照片确认诏版为残片及其形制，再看局部照片逐字辨认铭文。可将展签释文与器物表面刻字对照，注意文字排列方向与刻划深浅，以理解诏书的完整内容与残存情况。",
      "evidence_note": "展签/展签文字直接支持的有：名称“秦二世铜诏版”、年代“秦（公元前209年）”、出土信息“1982年咸阳渭城区长陵车站金属窖藏”、材质“铜”、释文内容。未确认而留空的有：尺寸、完整形制、现藏单位。",
