      "description": "展签显示此物名为“夔（kui）龙纹大瓦当”，英文名称为“Large eaves-end roof tile with kui dragon decoration”，年代为秦（公元前221－前206年），出土于1993年兴平侯村黄山宫遗址。照片可见瓦当的圆形当面，表面饰有夔龙纹。夔龙纹构图可在局部照片中辨认，纹样线条粗犷，具有秦代建筑装饰的典型特征。瓦当的厚度与背面的筒瓦部分未能从照片中明确分辨。",
      "significance": "该瓦当出土于黄山宫遗址，为秦代宫殿建筑提供了实物资料。夔龙纹大瓦当的纹饰风格可用于与同时期其他建筑遗址出土的瓦当进行类型学比较，有助于研究秦代建筑装饰艺术与宫殿营建制度。",
      "viewing_notes": "观看时可先看瓦当正面的整体构图，注意夔龙纹的形态与对称关系，再观察纹饰线条的深浅和粗细变化。如有局部照片可重点查看龙首、龙身细节，并与展签文字相互印证。",
