      "summary": "这组照片记录了一件秦代龙纹空心砖。照片包括砖体正面及局部纹饰。砖面饰有龙纹，属于秦咸阳城宫殿建筑遗址出土的大型空心砖构件。",
      "description": "展签显示此物名为“龙纹空心砖”，英文名称为“Hollow brick with dragon decoration”，年代为秦（公元前221－前206年），出土于1980年咸阳渭城区牛羊村秦咸阳城宫殿遗址。照片可见空心砖整体及表面的龙纹装饰。砖体为长方形，体积较大，龙纹以浮雕或模印方式表现，纹饰可在正面照片中辨认。空心结构无法直接从照片确认，但展签名称明确标注。",
      "significance": "该空心砖出土于秦咸阳城宫殿遗址，是秦代宫殿建筑的重要实物。龙纹空心砖的形制与纹饰可用于研究秦代大型建筑构件的制作技术、装饰风格及宫殿建筑的等级标识。",
      "viewing_notes": "观看时先确认砖体整体形制，再看龙纹的布局与具体形态。可将正面的整体照片与局部照片对照，观察龙纹的线条细节和模印痕迹，并注意砖体表面的残损剥落情况。",
      "evidence_note": "展签/展签文字直接支持的有：名称“龙纹空心砖”、年代“秦（公元前221－前206年）”、出土地点“1980年咸阳渭城区牛羊村秦咸阳城宫殿遗址”。未确认而留空的有：尺寸、材质（名称表明为空心砖，但展签文字未直接标注材质）、现藏单位。",
