      "title": "“北宫乐府”石磬",
      "category": "乐器",
      "period": "秦（公元前221－前206年）",
      "dimensions": "",
      "findspot": "2018年咸阳渭城区胡家沟府库建筑遗址F3",
      "material": "石",
      "theme": "秦代礼乐制度与乐府机构",
      "summary": "这组照片记录了一件秦代“北宫乐府”铭文石磬。照片包括石磬整体、局部铭文以及展签。展签说明石磬发现于府库建筑F3内，出土时为碎块，侧面有“北宫乐府”、数字编号、音律等文字。",
      "description": "展签显示此物名为““北宫乐府”石磬”，英文名称为“Stone chime (qing) with characters ‘Bei Gong Yue Fu’”，年代为秦（公元前221－前206年），出土于2018年咸阳渭城区胡家沟府库建筑遗址F3。展签文字说明石磬集中发现于府库建筑F3内，共计约600余公斤，出土时均为碎块，表面有火烧和砸击痕迹，侧面有“北宫乐府”、数字编号、音律等文字。图版标注了石磬各部位名称，如股、鼓、通长、通高等。照片可见石磬形制，侧面铭文在局部照片中可辨认。",
      "significance": "展签明确指出，石磬侧面的“北宫乐府”铭文是秦代设立乐府机构以及北宫存在的实物证据。石磬表面的人为损坏痕迹说明曾遭严重破坏。该资料对研究秦代礼乐制度、乐府机构设置及宫廷建筑布局具有重要价值。",
      "viewing_notes": "观看时先看石磬整体形制，注意股、鼓等部位的划分。再看局部铭文照片，辨认“北宫乐府”四字及数字编号。可将展签的图文标注与器物照片对照，理解石磬各部分的名称，并注意观察表面火烧和砸击痕迹。",
      "evidence_note": "展签/展签文字直接支持的有：名称““北宫乐府”石磬”、年代“秦（公元前221－前206年）”、出土地点“2018年咸阳渭城区胡家沟府库建筑遗址F3”、材质“石”、铭文内容“北宫乐府”、展签说明的出土状况及“通长126”标注。未确认而留空的有：完整尺寸数据（“126”具体单位未确认）、现藏单位。",
