      "summary": "这组照片记录了秦代石磬残块。照片包括残块的整体与局部。展签显示这些残块出土于咸阳渭城区胡家沟府库建筑遗址F3，属于秦代，材质为石。",
      "description": "展签显示此物名为“石磬残块”，英文名称为“Fragment of stone chime (qing)”，年代为秦（公元前221－前206年），出土地点为2018年咸阳渭城区胡家沟府库建筑遗址F3。照片可见石磬残块的形状不规则，为破碎后的残片。部分照片可观察到残块表面较平整，可能为磬面的一部分。残块上的铭文或刻痕在展签文字中未能明确识别。",
      "significance": "石磬残块与“北宫乐府”石磬同出一处遗址，为秦代宫廷乐府用器的制作、使用及损毁情况提供了实物资料。残块可与其他石磬资料结合，用于研究秦代礼乐器的材质、加工工艺及埋藏背景。",
      "viewing_notes": "观看时先确认残块的整体形态和不规则断裂面，再观察表面是否有磨光或刻划痕迹。可将多个残块照片互相比较，留意是否有可拼接的边沿，并对照同组“北宫乐府”石磬的形制理解残块在原器中的位置。",
      "evidence_note": "展签/展签文字直接支持的有：名称“石磬残块”、年代“秦（公元前221－前206年）”、出土地点“2018年咸阳渭城区胡家沟府库建筑遗址F3”、材质“石”。未确认而留空的有：尺寸、铭文内容、现藏单位。",
