      "theme": "战国秦陵随葬制度",
      "summary": "这组照片记录了神禾原秦陵的陵园平面图及相关随葬品。照片包括陵园平面图展板，以及金柄铁削、错银铜器座、“内史之印”封泥、“北宫乐府”石磬等器物的展签。这些物品出土于西安长安区神禾原秦陵。",
      "description": "展签可见“神禾原秦陵园平面图”及“神禾原秦陵发掘”等字样。另有展签显示“金柄铁削”“错银铜器座（底面）及铺首”““内史之印”封泥”““北宫乐府”石磬”等器物，年代均标为战国晚期，出土地点均为2005年西安长安区神禾原秦陵M1。照片内容包含陵园平面图展板和上述器物的展签。陵园平面图展示了陵园的整体布局，但具体结构细节在照片中难以辨认。",
      "significance": "神禾原秦陵是战国晚期秦国的陵墓，其陵园平面图为研究秦国王陵的布局和陵寝制度提供了资料。随葬品如“内史之印”封泥、“北宫乐府”石磬等，对研究秦国的官制、乐府机构及随葬品组合具有比较研究价值。",
      "viewing_notes": "观看时先看陵园平面图展板，理解陵园的总体范围与主要区域划分。再看各随葬品的展签，注意每件器物的名称、材质和出土位置。可将展签中的器物名称与后续相关组别的照片进行对照，建立陵园与随葬品的对应关系。",
      "evidence_note": "展签/展签文字直接支持的有：陵园平面图展板、“金柄铁削”“错银铜器座”“内史之印”封泥、“北宫乐府”石磬等器物名称、年代“战国晚期”、出土地点“2005年西安长安区神禾原秦陵M1”。未确认而留空的有：陵园模型的实物形态、尺寸、器物详细材质（部分展签未全部列出）、现藏单位。",
