      "summary": "这组照片记录了一件战国晚期的铭文铜匜。照片包括器物整体、底部铭文及展签。展签可辨读铭文内容，包括“私官二斗”“十五斤十五两”“今中府”等，出土于神禾原秦陵M1。",
      "description": "展签显示此物名为“铭文铜匜（yi）”，英文名称为“Bronze pouring vessel (yi) with inscription”，年代为战国晚期，出土于2005年西安长安区神禾原秦陵M1。展签上可见释文内容，包括“私官二斗”“十五斤十五两”“今中府”等铭文。照片可见铜匜的器形，包括流、腹、鋬等部分。铭文位于器身或底部，局部照片可辨认部分文字。器表保存状况可从照片中观察。",
      "significance": "铜匜铭文记录了容量和重量信息，如“私官二斗”“十五斤十五两”，反映了战国晚期秦国的度量衡制度及器物管理制度。“私官”等职官名称也见于其他出土文献，此类铭文对研究秦国官制与手工业管理具有重要价值。",
      "viewing_notes": "观看时先看铜匜的整体器形，确认流、腹、鋬的结构。再看铭文局部照片，对照展签释文逐字辨认。注意铭文的刻划位置（器身或底部）与字体风格，并观察器表的锈蚀与残损情况。",
      "evidence_note": "展签/展签文字直接支持的有：名称“铭文铜匜（yi）”、年代“战国晚期”、出土地点“2005年西安长安区神禾原秦陵M1”、材质“铜”、铭文释文“私官二斗”“十五斤十五两”“今中府”。未确认而留空的有：尺寸、完整器形细节、现藏单位。",
