      "material": "金、绿松石、琉璃、铜、银",
      "theme": "战国晚期高等级随葬品",
      "summary": "这组照片记录了神禾原秦陵出土的多件金带饰、金花饰、嵌金泡绿松石饰、心形琉璃饰件以及铜车马器等。展签显示年代为战国晚期，出土于神禾原秦陵M1及其外藏坑K2、K5、K8、K10。",
      "description": "展签可见多件器物的名称与信息。金带饰、金花饰年代为战国晚期，出土于2005年西安长安区神禾原秦陵M1。嵌金泡绿松石饰、心形琉璃饰件出土于2006年西安长安区神禾原秦陵外藏坑K8或K10。另有铜軎（wei）、鎏银铜辖、鎏金兽面纹铜节约、银合页、鎏金铜络饰、鎏金铜盖弓帽等车马器，分别出土于外藏坑K2、K5、K8、K10。照片可见这些饰件与车马器的形态，包括金饰的造型、绿松石和琉璃饰件的颜色与形状，以及车马器的金属质感与鎏金痕迹。各器物的具体细节分布在多张照片中。",
      "significance": "这批金、绿松石、琉璃饰件及车马器出土于神禾原秦陵及其外藏坑，反映了战国晚期秦国高等级墓葬的随葬品组合与奢侈品工艺。嵌金泡绿松石饰和心形琉璃饰件体现了多种材质的复合加工技术，车马器则对研究战国车制与金属细工具有比较价值。",
      "viewing_notes": "观看时先根据展签数字编号区分各组饰件和车马器，再分别查看每件器物的局部照片。注意金带饰、金花饰的造型差异，绿松石与琉璃饰件的颜色和镶嵌方式，以及车马器表面的鎏金、鎏银装饰。可将展签上的出土地点（如K8、K10）与器物对应记录。",
      "evidence_note": "展签/展签文字直接支持的有：器物名称“金带饰”“金花饰”“嵌金泡绿松石饰”“心形琉璃饰件”“铜軎”“鎏银铜辖”“鎏金兽面纹铜节约”“银合页”“鎏金铜络饰”“鎏金铜盖弓帽”、年代“战国晚期”、出土地点“2005/2006年西安长安区神禾原秦陵M1及外藏坑K2/K5/K8/K10”。未确认而留空的有：尺寸、每件器物的完整材质配比、现藏单位。",
