      "description": "展签显示“石胄”与“石铠甲”，英文名称分别为“Stone helmet”和“Stone armor”。年代均为秦（公元前221－前206年），材质为石，出土地点为1998年秦始皇帝陵园K9801陪葬坑（石铠甲坑）。照片可见展签及相关的器物照片。石胄为头盔形，石铠甲由多片石片组成，具体形制和编缀方式需在照片中辨认。部分照片可能展示了石铠甲的结构细节。",
      "significance": "K9801陪葬坑是秦始皇帝陵的重要陪葬坑，出土的石胄、石铠甲是秦代军事装备的实物资料。石质仿制铠甲体现了秦始皇帝陵随葬制度的特点，对研究秦代军事装备、石作工艺及陵寝制度具有重要价值。",
