      "description": "展签显示“青铜鸿雁”，英文名称为“Bronze swan goose”，年代为秦（公元前221－前206年），材质为铜，出土地点为2002年秦始皇帝陵K0007陪葬坑（青铜水禽坑）。照片可见展签及青铜鸿雁的形态。照片中可观察到鸿雁的造型为站立姿态，身体比例与真实鸟类相似。具体的羽毛表现细节和铸造工艺需在照片中辨认。",
      "significance": "青铜鸿雁出土于秦始皇帝陵K0007陪葬坑，该坑因出土青铜水禽而被称为“青铜水禽坑”。此类大型写实青铜动物雕塑是秦代青铜铸造工艺的杰出代表，反映了秦始皇帝陵随葬品的丰富品类和高度写实的艺术风格，对研究秦代雕塑艺术与工艺技术具有重要价值。",
