      "description": "展签可见““寺工”铭铜矛”“错金铜弩机及弩臂铜饰”“铜镞”““丽山（si）官”铭陶器盖”等名称，年代均为秦（公元前221－前206年）。出土地点包括1989年秦始皇帝陵陵园、1979年秦始皇帝陵兵马俑坑等。照片可见铜矛的锋刃、弩机的错金装饰、铜镞的基本形状及陶器盖的形态。铭文“寺工”“丽山”等在展签上标明。",
      "significance": "“寺工”铭文是秦代官营手工业机构的标识，铜矛上的铭文对研究秦代兵器生产管理与工官制度具有直接价值。错金铜弩机体现了秦代兵器制作的精湛工艺。陶器盖上的“丽山”铭文则与秦始皇帝陵的名称相关，对研究陵园制度有重要意义。",
      "viewing_notes": "观看时先将展签上的名称与对应器物照片匹配，再观察各器物的铭文和装饰细节。注意铜矛上的铭文位置与刻法，弩机上的错金纹样，以及铜镞的形制差异。",
      "evidence_note": "展签/展签文字直接支持的有：名称““寺工”铭铜矛”“错金铜弩机及弩臂铜饰”“铜镞”““丽山（si）官”铭陶器盖”、年代“秦（公元前221－前206年）”、部分出土地点“1989年秦始皇帝陵陵园”“1979年秦始皇帝陵兵马俑坑”。未确认而留空的有：具体尺寸、部分器物的完整出土地点、现藏单位。",
