      "summary": "这组照片记录了一件西汉金牌饰。展签详细描述了该牌饰的形制、尺寸、制作工艺和纹样题材，包括人骑巨龙、人骑奔牛、人骑奔马和卧熊等，并指出其具有北方鄂尔多斯文化特征和斯基泰文化影响。",
      "description": "展签显示此物名为“金牌饰”，英文名称为“Gold plaque”，年代为西汉（公元前206－公元8年），出土于2001年西安雁塔区缪家寨马腾空墓地M15。展签描述：平面呈长方形，横剖呈拱形，长20、宽8厘米，中间是不规则长方形孔，用4块相互缀连的玛瑙板填补。制作工艺采用锤、模压及镶嵌。主要纹样题材为人骑巨龙、人骑奔牛、人骑奔马和一头卧熊。展签还说明整体造型及纹样风格具有中国北方鄂尔多斯及邻近地区的文化特征，受到斯基泰文化的影响。照片可见牌饰的正面形状与纹样。",
      "significance": "展签明确指出该金牌饰的纹样风格具有中国北方鄂尔多斯地区文化特征，并受到斯基泰文化影响，体现了西汉时期地域间的文化交流。此类牌饰对研究欧亚草原文化传播、西汉时期装饰工艺及丧葬习俗具有重要的比较研究价值。",
      "viewing_notes": "观看时先看牌饰的整体形状，确认长方形与拱形横截面。再看纹样细节，辨认人骑巨龙、人骑奔牛、人骑奔马和卧熊的题材。注意中央的不规则长方形孔和玛瑙嵌补的痕迹，并观察金器表面的锤揲和模压痕迹。",
      "evidence_note": "展签/展签文字直接支持的有：名称“金牌饰”、年代“西汉（公元前206－公元8年）”、出土地点“2001年西安雁塔区缪家寨马腾空墓地M15”、尺寸“长20、宽8厘米”、材质“金、玛瑙”、纹样题材与风格描述。未确认而留空的有：现藏单位。",
