      "description": "展签显示“虎纹踏步”与“水管弯头”，英文名称分别为“Rectangular brick step with tiger pattern”和“Connector bend of drain pipe”。年代为西汉（公元前206－公元8年），出土地点为2010年千阳尚家岭遗址。照片可见虎纹踏步为长方形砖，表面饰有虎纹图案。水管弯头为管状弯折结构，用于连接排水管道。两者的陶质表面状况可从照片中观察。",
      "significance": "虎纹踏步和水管弯头是西汉时期建筑遗址出土的构件，反映了当时建筑装饰和排水设施的技术水平。虎纹踏步的纹饰可用于研究西汉建筑装饰题材，水管弯头则对了解西汉城市或宫殿排水系统具有资料价值。",
      "viewing_notes": "观看时先看虎纹踏步的整体形状和虎纹的布局，再看水管弯头的弯折角度和接口形态。注意砖表面的纹饰深浅和磨损情况，以及管道构件的陶质与制作痕迹。",
