      "significance": "阳陵为西汉景帝陵墓，其南区外藏坑出土的彩绘陶塑动物是西汉帝陵随葬制度的重要组成部分。这些陶塑反映了当时家禽和动物的饲养情况，也展示了西汉陶塑艺术的写实风格与彩绘工艺，对研究汉代丧葬习俗与造型艺术具有价值。",
