      "summary": "这组三张照片记录的是北周武帝孝陵志。展签标注其时代为北周，出土于1994年咸阳渭城区陈马村孝陵，英文题名称之为北周武帝孝陵的墓志。照片序列中前半部分为器物拍摄，末张为展签。",
      "description": "展签可辨的名称是“北周武帝孝陵志”，英文对应为Epitaph of the Xiaoling Mausoleum of Emperor Wu of Northern Zhou Dynasty，时代标注为北周（公元557-581年），出土信息为1994年咸阳渭城区陈马村孝陵。前两张照片可见墓志石体的正面与侧面，因无局部文字特写展签文字，铭文内容未能逐字辨识。第三张为展签照片。",
      "significance": "北周武帝宇文邕是北周重要君主，其孝陵墓志是确认陵墓归属与帝系世系的关键石刻材料。此墓志可用于与同期北周宗室墓葬出土石刻比较，观察北周晚期墓志文体、书法风格与谥号制度。",
      "viewing_notes": "先看第二张照片中墓志石面文字布局，再看第一张整体形制。因组内无局部特写，可在展签照片中核对名称与出土信息，再结合其他北周墓志照片比较形制与书风。",
      "evidence_note": "展签/展签文字直接支持：名称、时代、出土信息。未确认而留空：尺寸、材质、铭文全文。",
