      "significance": "白釉长颈瓶是隋代白瓷的代表器形之一。此瓶出土于有明确纪年的隋丰宁公主墓，可用于研究隋代白瓷的器形演变、釉料配方及隋代瓷器在墓葬随葬品中的地位。",
