      "start": 463,
      "end": 466,
      "title": "塔式罐",
      "category": "陶器",
      "period": "唐景云元年（710）",
      "dimensions": "",
      "findspot": "1995年富平南牌（完整名称待确认）",
      "material": "陶",
      "theme": "随葬明器",
      "summary": "这组四张照片记录一件唐代塔式罐。展签标注时代为唐景云元年（710），出土于1995年富平南牌（展签文字不完整）。展板详细说明塔式罐因盖钮形似塔而得名，多彩绘陶质并贴塑仰覆莲瓣、兽首等装饰，用于随葬。",
      "description": "展签可辨名称为“塔式罐”，英文为Jar in pagoda form。时代为唐景云元年（710），出土信息展签文字为“1995年富平南牌”，完整出土单位待确认。展板文字说明：因盖钮形似塔而得名，多彩绘陶质并贴塑仰覆莲瓣、兽首等装饰，专门用于随葬，通常置于墓室西北角或与镇墓俑相邻，具有供奉礼仪性质，流行于盛、中唐时期。另一展板标注“节愍太子墓出土塔式罐”并配有结构示意图，说明罐身八等分、贴饰浮雕象头与兽面各4个、束腰形座一周13瓣覆莲、覆盆形座一周分8格等细节。照片可见塔式罐整体形制与贴塑装饰。",
      "significance": "塔式罐是盛唐至中唐时期典型的随葬明器，其名称与用途在展板中已有明确说明。此件与节愍太子墓出土塔式罐同属唐景云元年（710）时期，可用于研究唐代塔式罐的形态演变、贴塑工艺、随葬位置与佛教影响下的丧葬观念。",
      "viewing_notes": "先看第三、四张展板与结构示意图，了解塔式罐各部位的名称（盖钮、罐身、束腰形座、覆盆形座）与装饰分布。再看前两张器物照片，按示意图逐层核对仰莲、覆莲、象头与兽面浮雕的实际位置。",
      "evidence_note": "展签/展板/展签文字直接支持：名称、时代（唐景云元年710）、功能说明、装饰结构说明（节愍太子墓出土塔式罐结构示意）、材质类别。未确认而留空：完整出土单位（“富平南牌”后文字缺失）、尺寸、具体釉色。",
      "display_sequences": [
        463,
        464
      ],
      "label_sequences": [
        465,
        466
      ],
      "source_excerpt": "盛行密不可分。也有认为 | 塔式罐即五谷仓，盛装谷物供墓主享用。 | 维景雪元年成火庚成 | 朔二 | 太子哀册 | (710) 塔式罐 | Jar in pagoda form | 唐景云元年（7 | 1995年富平南牌 塔式罐 | JARINPAGODAFORM | 因盖钮形似塔被称为“塔式罐”，多彩 | 绘陶质并贴塑仰覆莲瓣、兽首等装饰。专用 | 于随葬，通常置于墓室西北角或与镇墓俑相 | 邻，具有供奉礼仪性质。流行于盛、中唐时 | 期，与唐代佛教的盛行密不可分。也有认为 | 塔式罐即五谷仓，盛装谷物供墓主享用。 竖九层直塔形钮 | 罐身八等分，贴饰浮雕 | 象头、兽面各4个 | 周18瓣仰莲 | 一周贴模制浮雕象头3个 | 束腰形座 | 周13瓣覆莲 | 一周分8格，格内贴模制 | 覆盆形座 | 浮雕象头及兽面相间排列 | 节慰太子墓出土塔式罐。",
