      "summary": "这组四张照片记录唐代马球图壁画。展签说明壁画2004年出土于陕西省富平县北吕村唐嗣虢王李邕墓，位于墓葬前甬道西壁，描绘击打马球的瞬间，骑者视线聚焦于下方马球，挥杆击球，动感十足。",
      "description": "展签可辨名称为“马球图”，英文为Mural of Polo Match。展签文字说明：2004年出土于陕西省富平县北吕村唐嗣虢王李邕墓；壁画位于墓葬前甬道西壁，描绘了击打马球的精彩瞬间；骑者视线皆聚焦于下方马球，挥杆击球，动感十足。照片可见壁画残片，绘有人物骑马挥杆的姿态，画面中马匹与人物动态明显。前几张照片未见可辨展签文字文字，实际画面内容需直接观察。",
      "significance": "马球图是唐代墓葬壁画中反映贵族体育活动的珍贵图像资料。此壁画出自唐嗣虢王李邕墓，墓主身份明确，可用于研究唐代马球运动的流行、绘画技法及唐代贵族墓葬壁画的题材选择。",
      "viewing_notes": "先看第四张展签文字，明确壁画出土位置与内容描述。再回看前三张壁画照片，注意骑者视线方向、挥杆动作与马匹动态的呼应关系，并观察画面残损边界与保存状态。",
      "evidence_note": "展签/展签文字直接支持：名称、出土信息（2004年富平县北吕村唐嗣虢王李邕墓）、位置（前甬道西壁）、内容描述（骑者视线、挥杆击球、动感）。未确认而留空：壁画尺寸、保存状态细节、画面完整场景描述。",
