      "summary": "这组三张照片记录一件北宋铭文石敦。展签标注时代为北宋元祐八年（1093），出土于2008年蓝田吕氏家族墓园M2。前两张为器物铭文的局部拍摄，末张为展签。",
      "description": "展签可辨名称为“铭文石敦（dui）”，英文为Stone tripod food vessel (dui) with inscription。时代为北宋元祐八年（1093），出土于2008年蓝田吕氏家族墓园M2。照片可见一件石质敦形器，器身有铭文。前两张照片中展签文字仅识别出零散文字如“典叔召敦之”“書省正字”“宋左奉谈”等，因识别质量低，铭文未能通读。末张为展签。",
      "significance": "铭文石敦出自蓝田吕氏家族墓园，该墓园是北宋关中士族墓葬的重要发现。此件仿古石敦带铭文，可用于研究北宋士族对三代礼器的仿制风气、金石学影响以及蓝田吕氏的家族文化与丧葬礼仪。",
      "viewing_notes": "先看第三张展签确认名称、时代与出土信息。再回看第一、二张铭文局部照片，尝试从右至左逐行阅读铭文。因展签文字质量低，建议在展厅中直接观察铭文刻字，注意字口深度与书体风格。",
