      "summary": "这组照片记录秦始皇帝陵园K0007陪葬坑出土的彩绘铜鸿雁与铜天鹅，包含立姿与卧姿的不同形态。展签显示这些铜禽出土于2002年发掘的K0007陪葬坑。",
      "description": "展签可辨器物名称包括“彩绘卧姿铜鸿雁”“彩绘立姿铜鸿雁”“彩绘卧姿铜天鹅”“彩绘立姿铜天鹅”。时代标注为秦，出土信息为2002年秦始皇帝陵园K0007陪葬坑。照片可见鸿雁与天鹅的立姿、卧姿造型，表面应有彩绘痕迹。坑内还有小件器物与二层台等遗迹信息。具体彩绘颜色与身体细节须由局部照片确认。",
      "significance": "秦始皇帝陵园K0007陪葬坑出土的铜水禽是研究秦代宫廷苑囿与雕塑工艺的重要资料。彩绘铜鸿雁与铜天鹅的造型差异有助于了解当时对水禽的写实表现。坑内布局与器物组合的进一步研究可补充对陪葬坑功能的认识。",
      "viewing_notes": "先看展签确认出土地与坑位，再对比鸿雁与天鹅的立姿、卧姿照片。注意观察彩绘残留的位置与颜色。最后结合陪葬坑平面图，理解铜禽在坑内的分布。",
      "evidence_note": "展签/展签文字直接支持：名称、时代（秦）、出土地（秦始皇帝陵园K0007陪葬坑，2002年）、材质（铜）。未确认而留空：尺寸、彩绘具体颜色。",
