      "summary": "这组照片记录范铸工艺说明展板与一件西周兽面纹铜鼎。展签显示铜鼎出土于宝鸡市渭滨区峪泉村墓葬，并标注其采用范铸成型。",
      "description": "展签说明文字涉及范铸工艺的基本原理，包括制模、制范、浇注与铸后加工等步骤。兽面纹铜鼎展签标明时代为西周，出土地为1998年宝鸡市渭滨区峪泉村M5。照片可见鼎身为三足两耳造型，腹部应有兽面纹装饰。范铸工艺的铸缝或浇口痕迹须由器表局部照片确认。",
      "significance": "兽面纹铜鼎是西周青铜礼器的常见形制，此件与范铸工艺说明并置，可作为理解青铜器铸造流程的实物例证。器表铸缝等痕迹对研究制作工艺有直接价值。具体铸造细节需要器物观察确认。",
      "viewing_notes": "先读范铸工艺说明展板，理解制模、制范、浇注流程。再观察铜鼎的整体轮廓与三足两耳比例。随后将镜头靠近腹部兽面纹与器表，寻找范线或铸缝痕迹。",
      "evidence_note": "展签/展签文字直接支持：名称（兽面纹铜鼎）、时代（西周）、出土地（宝鸡市渭滨区峪泉村M5，1998年）、工艺说明（范铸成型）。未确认而留空：尺寸、具体铸造痕迹。",
